public sealed class OrdersReportDataProvider : IReportDataProvider
{
    public Task<ReportDataSetResult> GetDataAsync(
        string dataSetName,
        ReportDataQuery query,
        IReadOnlyDictionary<string, ReportParameterValue> parameters,
        ReportExecutionContext context)
    {
        var schema = new[]
        {
            new ReportDataColumn("Region", ReportDataFieldType.String),
            new ReportDataColumn("Total", ReportDataFieldType.Number)
        };

        return Task.FromResult(new ReportDataSetResult(schema, LoadRowsAsync(context.CancellationToken)));
    }
}
